                SemanticPrecedence = reader.GetString(reader.GetOrdinal("semantic_precedence")),
                SemanticProgress = reader.IsDBNull(reader.GetOrdinal("semantic_progress")) ? (string?)null : reader.GetString(reader.GetOrdinal("semantic_progress")),
                SourceScenarioVersionPk = reader.IsDBNull(reader.GetOrdinal("source_scenario_version_pk")) ? (long?)null : reader.GetInt64(reader.GetOrdinal("source_scenario_version_pk")),
                ToNodePk = reader.GetInt64(reader.GetOrdinal("to_node_pk")),
                TopologyRole = reader.GetString(reader.GetOrdinal("topology_role"))
            };
        }
        
        private static readonly Dictionary<string, string> _columnNames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            { "CanonicalPointer", "_canonical_pointer" },
            { "CanonicalPointerKey", "_canonical_pointer_key" },
            { "OwnerDefinitionPk", "_owner_definition_pk" },
            { "BindingAuthorityDefinitionPk", "binding_authority_definition_pk" },
            { "BlueprintEdgePk", "blueprint_edge_pk" },
