            { "SemanticPrecedence", "semantic_precedence" },
            { "SemanticProgress", "semantic_progress" },
            { "SourceScenarioVersionPk", "source_scenario_version_pk" },
            { "ToNodePk", "to_node_pk" },
            { "TopologyRole", "topology_role" },
        };

        private static string GetColumnName(string propertyName)
        {
            return _columnNames.TryGetValue(propertyName, out var columnName) ? columnName : propertyName;
        }

        private string BuildSqlQuery(QueryDetail<BlueprintEdge> queryDetail)
        {
            var whereClauses = new List<string>();
            int index = 0;
            foreach (var criteria in queryDetail.SearchCriteria)
            {
                string columnName = GetColumnName(criteria.GetColumnName());
                if (criteria.TrimSpaces) columnName = $"TRIM({columnName})";
                string sqlOperator = QueryDetail<BlueprintEdge>.GetSqlOperator(criteria.Operator);
                whereClauses.Add($"{columnName} {sqlOperator} @{criteria.GetColumnName()}{index}");
                index++;
            }

            string whereClause = whereClauses.Any() ? "WHERE " + string.Join(" AND ", whereClauses) : string.Empty;

            var orderByClauses = new List<string>();
            foreach (var orderBy in queryDetail.OrderByList)
            {
                orderByClauses.Add($"{GetColumnName(orderBy.GetColumnName())} {QueryDetail<BlueprintEdge>.GetSqlDirection(orderBy.Direction)}");
            }

            string orderByClause = orderByClauses.Any() ? "ORDER BY " + string.Join(", ", orderByClauses) : "ORDER BY blueprint_edge_pk";

            return $@"SELECT e.* FROM (SELECT * FROM [model].[blueprint_edge]  ) e {whereClause} {orderByClause}
                  OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY";
        }
        
        public void MapValuesToBlueprintEdgeParameters(SqlCommand command, BlueprintEdge entity)
        {
            command.Parameters.AddWithValue("@CanonicalPointer", entity.CanonicalPointer);
            command.Parameters.AddWithValue("@CanonicalPointerKey", entity.CanonicalPointerKey ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@OwnerDefinitionPk", entity.OwnerDefinitionPk);
            command.Parameters.AddWithValue("@BindingAuthorityDefinitionPk", entity.BindingAuthorityDefinitionPk);
            command.Parameters.AddWithValue("@BlueprintEdgePk", entity.BlueprintEdgePk);
            command.Parameters.AddWithValue("@BlueprintVersionPk", entity.BlueprintVersionPk);
            command.Parameters.AddWithValue("@ContractRelation", entity.ContractRelation ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@EdgeId", entity.EdgeId);
            command.Parameters.AddWithValue("@FromNodePk", entity.FromNodePk);
            command.Parameters.AddWithValue("@ProjectionOrdinal", entity.ProjectionOrdinal);
            command.Parameters.AddWithValue("@SelectingVariantPk", entity.SelectingVariantPk ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@SemanticPrecedence", entity.SemanticPrecedence);
            command.Parameters.AddWithValue("@SemanticProgress", entity.SemanticProgress ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@SourceScenarioVersionPk", entity.SourceScenarioVersionPk ?? (object)DBNull.Value);
            command.Parameters.AddWithValue("@ToNodePk", entity.ToNodePk);
